def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    scores = np.where(valid, - (rem ** 3) + 5.0 * np.log(rem + 1e-5), -np.inf)
    return scores
